import { assign, removeNode } from './util';
import { createVNode, Fragment, applyRef } from './create-element';
import { diff, unmount } from './diff/index';
import { EMPTY_OBJ, EMPTY_ARR } from './constants';
import { getDomSibling } from './component';

/**
 * Clones the given VNode, optionally adding attributes/props and replacing its children.
 * @param {import('./internal').VNode} vnode The virtual DOM element to clone
 * @param {object} props Attributes/props to add when cloning
 * @param {Array<import('./internal').ComponentChildren>} rest Any additional arguments will be used as replacement children.
 * @returns {import('./internal').VNode}
 */
export function cloneElement(vnode, props, children) {
	let normalizedProps = assign({}, vnode.props),
		key,
		ref,
		i;
	for (i in props) {
		if (i == 'key') key = props[i];
		else if (i == 'ref') ref = props[i];
		else normalizedProps[i] = props[i];
	}

	if (arguments.length > 3) {
		children = [children];
		for (i = 3; i < arguments.length; i++) {
			children.push(arguments[i]);
		}
	}
	if (children != null) {
		normalizedProps.children = children;
	}

	return createVNode(
		vnode.type,
		normalizedProps,
		key || vnode.key,
		ref || vnode.ref,
		null
	);
}

/**
 * Owns the parent DOM node while walking a bailed-out child tree.
 * @param {import('./internal').PreactElement} parentDom
 */
function ChildOrder(parentDom) {
	this._parentDom = parentDom;
}

/**
 * Re-place host children after a component bails out of rendering.
 * @param {import('./internal').VNode} childVNode
 * @param {import('./internal').PreactElement} oldDom
 * @returns {import('./internal').PreactElement}
 */
ChildOrder.prototype.reorderChildren = function(childVNode, oldDom) {
	let parentDom = this._parentDom;
	let children = childVNode._children;

	for (let tmp = 0; tmp < children.length; tmp++) {
		let vnode = children[tmp];
		if (vnode) {
			vnode._parent = childVNode;

			let nodeType = vnode.type;
			let component = vnode._component;
			let ref = vnode.ref;

			if (typeof nodeType == 'function' || component != null) {
				let walk = vnode;
				let contextType = nodeType.contextType;
				if (contextType != null) {
					if (
						contextType._id != null ||
						contextType._defaultValue !== undefined
					) {
						walk = vnode;
					}
				}
				if (ref != null && typeof ref != 'function' && ref.current != null) {
					applyRef(ref, ref.current, vnode);
				}
				this.reorderChildren(walk, oldDom);
			} else {
				let hostDom = vnode._dom;
				if (ref != null && typeof ref != 'function' && ref.current != null) {
					applyRef(ref, ref.current, vnode);
					if (hostDom == null) {
						hostDom = vnode._dom;
					}
				}
				if (
					hostDom != null &&
					(hostDom.parentNode !== parentDom || hostDom.nextSibling == oldDom)
				) {
					hostDom = vnode._dom;
				}
				oldDom = placeChild(
					parentDom,
					vnode,
					vnode,
					children,
					null,
					hostDom,
					oldDom
				);
			}
		}
	}

	return oldDom;
};

export function diffChildren(
	parentDom,
	renderResult,
	newParentVNode,
	oldParentVNode,
	globalContext,
	isSvg,
	excessDomChildren,
	commitQueue,
	oldDom,
	isHydrating
) {
	let i, j, oldVNode, childVNode, newDom, firstChildDom, refs;

	// This is a compression of oldParentVNode!=null && oldParentVNode != EMPTY_OBJ && oldParentVNode._children || EMPTY_ARR
	// as EMPTY_OBJ._children should be `undefined`.
	let oldChildren = (oldParentVNode && oldParentVNode._children) || EMPTY_ARR;

	let oldChildrenLength = oldChildren.length;

	// Only in very specific places should this logic be invoked (top level `render` and `diffElementNodes`).
	// I'm using `EMPTY_OBJ` to signal when `diffChildren` is invoked in these situations. I can't use `null`
	// for this purpose, because `null` is a valid value for `oldDom` which can mean to skip to this logic
	// (e.g. if mounting a new tree in which the old DOM should be ignored (usually for Fragments).
	if (oldDom == EMPTY_OBJ) {
		if (excessDomChildren != null) {
			oldDom = excessDomChildren[0];
		} else if (oldChildrenLength) {
			oldDom = getDomSibling(oldParentVNode, 0);
		} else {
			oldDom = null;
		}
	}

